import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import { URL } from 'url';

const app = express();
const ALLOWED_HOSTS = ['app.example.com', 'auth.example.com', 'cdn.example.com'];
const SESSION_SECRET = crypto.randomBytes(32).toString('hex');
const sessions = new Map<string, { user: string; expires: number }>();

interface RedirectConfig {
  allowSubdomains: boolean;
  enforceHttps: boolean;
  maxRedirects: number;
}

const config: RedirectConfig = {
  allowSubdomains: true,
  enforceHttps: true,
  maxRedirects: 3,
};

function normalizeUrl(input: string): string {
  // Handle protocol-relative URLs
  if (input.startsWith('//')) {
    input = 'https:' + input;
  }
  // Handle bare paths
  if (input.startsWith('/') && !input.startsWith('//')) {
    return input; // relative path, safe
  }
  return input;
}

function extractHost(urlString: string): string | null {
  try {
    const parsed = new URL(urlString);
    return parsed.hostname;
  } catch {
    return null;
  }
}

function isSubdomainOf(candidate: string, parent: string): boolean {
  // Check if candidate is a subdomain of parent
  const normalizedCandidate = candidate.toLowerCase();
  const normalizedParent = parent.toLowerCase();
  if (normalizedCandidate === normalizedParent) return true;
  return normalizedCandidate.endsWith('.' + normalizedParent);
}

function validateRedirectTarget(target: string): boolean {
  const normalized = normalizeUrl(target);

  // Allow relative paths
  if (normalized.startsWith('/') && !normalized.startsWith('//')) {
    return true;
  }

  const host = extractHost(normalized);
  if (!host) return false;

  // Check against allowed hosts
  for (const allowed of ALLOWED_HOSTS) {
    if (config.allowSubdomains) {
      if (isSubdomainOf(host, allowed)) return true;
    } else {
      if (host.toLowerCase() === allowed.toLowerCase()) return true;
    }
  }

  return false;
}

function sanitizeRedirectUrl(url: string): string {
  const normalized = normalizeUrl(url);

  if (config.enforceHttps) {
    try {
      const parsed = new URL(normalized);
      if (parsed.protocol === 'http:') {
        parsed.protocol = 'https:';
        return parsed.toString();
      }
    } catch {
      // If parsing fails, it's a relative URL
    }
  }

  return normalized;
}

function createSession(user: string): string {
  const token = crypto.randomBytes(24).toString('hex');
  sessions.set(token, { user, expires: Date.now() + 3600000 });
  return token;
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const token = req.cookies?.session;
  if (!token || !sessions.has(token)) {
    const returnUrl = req.query.returnUrl as string || req.originalUrl;
    res.redirect(`/login?returnUrl=${encodeURIComponent(returnUrl)}`);
    return;
  }
  const session = sessions.get(token)!;
  if (session.expires < Date.now()) {
    sessions.delete(token);
    res.redirect('/login');
    return;
  }
  next();
}

app.use(express.urlencoded({ extended: false }));

app.post('/auth/callback', (req: Request, res: Response) => {
  const { username, password, returnUrl } = req.body;

  // Simulate authentication
  if (!username || !password) {
    res.status(400).send('Missing credentials');
    return;
  }

  const sessionToken = createSession(username);
  res.cookie('session', sessionToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    maxAge: 3600000,
  });

  // Validate and redirect
  const target = returnUrl || '/dashboard';

  if (validateRedirectTarget(target)) {
    const safeUrl = sanitizeRedirectUrl(target);
    res.redirect(safeUrl);
  } else {
    res.redirect('/dashboard');
  }
});

app.get('/auth/logout', (req: Request, res: Response) => {
  const token = req.cookies?.session;
  if (token) sessions.delete(token);

  const postLogoutRedirect = req.query.redirect as string;
  if (postLogoutRedirect && validateRedirectTarget(postLogoutRedirect)) {
    res.redirect(sanitizeRedirectUrl(postLogoutRedirect));
  } else {
    res.redirect('/login');
  }
});

app.get('/auth/sso/initiate', (req: Request, res: Response) => {
  const callbackUrl = req.query.callback as string;
  const state = crypto.randomBytes(16).toString('hex');

  // Store state for CSRF protection
  sessions.set(`state:${state}`, { user: '', expires: Date.now() + 300000 });

  // Build SSO redirect - the callback is where we return after SSO
  const ssoUrl = `https://sso.example.com/authorize?state=${state}&callback=${encodeURIComponent(callbackUrl || '/dashboard')}`;
  res.redirect(ssoUrl);
});

app.get('/auth/sso/complete', (req: Request, res: Response) => {
  const { state, token, redirect_uri } = req.query as Record<string, string>;

  // Verify state
  const stateKey = `state:${state}`;
  if (!sessions.has(stateKey)) {
    res.status(403).send('Invalid state');
    return;
  }
  sessions.delete(stateKey);

  // Create session from SSO token
  const sessionToken = createSession(token || 'sso_user');
  res.cookie('session', sessionToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    maxAge: 3600000,
  });

  // The redirect_uri must be validated even though it came via SSO flow
  const destination = redirect_uri || '/dashboard';
  if (validateRedirectTarget(destination)) {
    const finalUrl = sanitizeRedirectUrl(destination);
    res.redirect(finalUrl);
  } else {
    res.redirect('/dashboard');
  }
});

// Graceful shutdown
let server: any;
const shutdown = () => {
  console.log('Shutting down gracefully...');
  sessions.clear();
  server?.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 5000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server = app.listen(3000, () => console.log('Auth service running on :3000'));

export { app, validateRedirectTarget, sanitizeRedirectUrl };
